// OM Lite fonts — generated data, declared here.
//
// font12 is the app's body face (chat, lists, settings, keys) and font18 is the top-bar title. Both are
// generated by tools/mkfont.py from DejaVu Sans at the exact pixel sizes, because scaling a bitmap font
// up duplicates rows and reads raggedly, and the built-in 6x8 is too small to be comfortable.
#pragma once

#include <LovyanGFX.hpp>

namespace om {

extern const lgfx::GFXfont font12;   // 12 px, ASCII 0x20-0x7E
extern const lgfx::GFXfont font18;   // 18 px, the "OM LITE" title

// Turn the app font on for a drawing surface (the panel and the off-screen frame each keep their own).
inline void useAppFont(lgfx::LovyanGFX* d) {
  if (d) d->setFont(&font12);
}

}  // namespace om
